    expect(saved.usableSeconds).toBe(6);
    expect(saved.steps.map((step) => [step.id, step.blocked])).toEqual([
      ["bootstrap", false],
      ["github", true],
      ["packs", true],
      ["plans", false],
      ["profile", true],
      ["apply", false],
