    const home = temp.make("home-");
    const box = fakeMachine(home, { github: 3, chatgpt: 2 }, { startedAt: start });
    const result = await hedgeSetup(home, ["--chat", "--preset", "starter", "--plan", "codex", "--devbox", "skip"], [], box);
    expect(result.code).toBe(0);
