describe("usable before the rest", () => {
  test("with both plans, the machine is usable once Claude passes, and ChatGPT and the final check follow", async () => {
    const home = temp.make("home-");
    const box = fakeMachine(home, { github: 3, chatgpt: 4 }, { startedAt: start });
    const result = await hedgeSetup(home, ["--chat", "--preset", "starter", "--plan", "both", "--devbox", "skip"], [], box);
    expect(result.code).toBe(0);
    const ready = result.output.indexOf("✓ Ready to use. Start a new thread in T3 Code now. Setup goes on with: Install Codex, Sign in to ChatGPT, Check everything.");
    expect(ready).toBeGreaterThan(result.output.indexOf("  ✓ Sign in to Claude: already done"));
    expect(ready).toBeLessThan(result.output.indexOf("▶ Install Codex"));
    expect(result.output.indexOf("▶ Install Codex")).toBeLessThan(result.output.indexOf("▶ Sign in to ChatGPT"));
    expect(result.skipped).toEqual([["base/codex-cli"], []]);
    expect(result.output).toContain("  Ready after     6s\n");
    expect(timings(home).usableSeconds).toBe(6);
    expect(timings(home).steps.at(-1)).toMatchObject({ id: "check", outcome: "done", end: "2026-11-11T10:00:14.000Z" });
  });

  test("without a person to wait for, installs Codex in the first apply, since the run stops at an open sign-in", async () => {
    const home = temp.make("home-");
    const result = await hedgeSetup(home, ["--non-interactive", "--preset", "starter", "--plan", "both", "--devbox", "skip"], [], fakeMachine(home, { claude: 5 }, { startedAt: start }));
    expect(result.code).toBe(2);
    expect(result.skipped).toEqual([[]]);
    expect(result.output).not.toContain("Install Codex");
  });

  test.each(["check", "check:coder.node-9"])("a setup that finished with %s before Codex waited for later does not apply again", async (finished) => {
    const home = temp.make("home-");
    const box = fakeMachine(home, {}, { startedAt: start });
    expect((await hedgeSetup(home, ["--chat", "--preset", "starter", "--plan", "both", "--devbox", "skip"], [], box)).code).toBe(0);
    const file = machineFile(home);
    const done = file.setup.done.filter((id: string) => id !== "apply-codex").map((id: string) => (id === "check" ? finished : id));
    writeFileSync(join(home, ".config/hedge/machine.json"), JSON.stringify({ ...file, setup: { ...file.setup, done } }));
    const again = await hedgeSetup(home, ["--chat", "--devbox", "skip"], [], box);
    expect(again.code).toBe(0);
    expect(again.applied).toEqual([]);
    expect(again.output).not.toContain("Install Codex");
  });

  test("a run that resumes after the machine became usable keeps the timing record and its usable mark", async () => {
    const home = temp.make("home-");
    const box = fakeMachine(home, { chatgpt: 3 }, { startedAt: start });
    const first = await hedgeSetup(home, ["--non-interactive", "--preset", "starter", "--plan", "both", "--devbox", "skip"], [], box);
    expect(first.code).toBe(2);
    const { usable, usableSeconds } = timings(home);
    expect(usable).not.toBeNull();
    const later = box.clock.now() + 3_600_000;
    box.clock.now = () => later;
    const again = await hedgeSetup(home, ["--chat", "--devbox", "skip"], [], box);
    expect(again.code).toBe(0);
    expect(timings(home)).toMatchObject({ usable, usableSeconds });
    expect(timings(home).steps.map((step) => step.id)).toEqual(expect.arrayContaining(["github", "claude", "chatgpt", "check"]));
    expect(again.output).toContain("  Ready after ");
  });

  test("signs in to a pack before the devbox question, since that sign-in can add the SSH hosts the question offers", async () => {
    const home = temp.make("home-");
    const box = fakeMachine(home, { coder: 1 }, { org: true, startedAt: start });
    const result = await hedgeSetup(home, ["--plan", "claude"], ["", "", "", "", ""], box, teamSource("acme"));
    const signIn = result.output.indexOf("Sign in to Coder");
    expect(signIn).toBeGreaterThan(-1);
    expect(signIn).toBeLessThan(result.output.indexOf("No devbox for now"));
  });

  test("with one plan, installs everything in one apply", async () => {
    const home = temp.make("home-");
    const result = await hedgeSetup(home, ["--chat", "--preset", "starter", "--plan", "codex", "--devbox", "skip"], [], fakeMachine(home, {}, { startedAt: start }));
    expect(result.code).toBe(0);
    expect(result.skipped).toEqual([[]]);
    expect(result.output).not.toContain("Install Codex");
  });

  test("asks the devbox question before the steps that can wait", async () => {
    const home = temp.make("home-");
    const result = await hedgeSetup(home, ["--preset", "starter", "--plan", "both"], ["", "", ""], fakeMachine(home, { chatgpt: 1 }, { startedAt: start }));
    expect(result.code).toBe(0);
    expect(result.output.indexOf("No devbox for now")).toBeLessThan(result.output.indexOf("✓ Ready to use"));
    expect(result.output.indexOf("✓ Ready to use")).toBeLessThan(result.output.indexOf("▶ Sign in to ChatGPT"));
  });
});

import { afterEach, describe, expect, test } from "bun:test";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { git, isolateGit, tempDirs } from "../testing/git.ts";
import { boxHome, boxMachineFile, engineRoot, fakeMachine, githubRepo, nodeEngine, nodeHas, setUpToAdd, throughSsh } from "./testing.ts";

isolateGit();
const temp = tempDirs();
afterEach(() => temp.cleanup());

const node = "coder.hedge-node-1";
const guarded = ["--add", "guards", "--workflows", "git-allowlist=on,oom-survival=on"];
const thisCommit = Bun.spawnSync(["git", "-C", engineRoot, "rev-parse", "HEAD"]).stdout.toString().trim();

async function signedUp(setupArgs: string[] = []) {
  const home = temp.make("home-");
  return { home, ...(await setUpToAdd(home, node, setupArgs)) };
}

const profileApplied = (home: string) => boxMachineFile(home, node).profileDir === join(boxHome(home, node), ".local/share/hedge/profile");
const linkedHere = ["https://box-1.relay.example"];
const listed = (output: string, say: string) => output.split("\n").filter((line) => line.startsWith(`  · ${say}`)).length;
const endList = (output: string) => output.slice(output.lastIndexOf(`Left for you on ${node}:`));
const notTheProfile = { node: { stepsFail: true } };
const enginePath = (home: string, path: string) => join(boxHome(home, node), ".local/share/hedge/engine", path);

describe("hedge devbox add applies the profile on the node", () => {
  test("runs none of the steps left for the person, though sudo there asks no password", async () => {
    const { home, io, add } = await signedUp(guarded);
    expect(await add(fakeMachine(home, {}, { node: {} }))).toBe(0);
    expect([nodeHas(home, node, "allowlist"), nodeHas(home, node, "earlyoom")]).toEqual([false, false]);
    expect(io.output()).not.toContain("  $ ");
  });

  test("goes on to the link step when only steps for the person are left, and lists each one once at the end, as a command that runs over plain SSH", async () => {
    const { home, io, add } = await signedUp(guarded);
    const box = fakeMachine(home, {}, { node: {} });
    expect(await add(box)).toBe(0);
    expect(box.peerLinks.here).toEqual(linkedHere);
    const output = io.output();
    expect(output).toContain(`  · 2 steps are left for you on ${node}. Hedge lists them at the end and runs none of them.`);
    expect(output.indexOf(`  ✓ Link T3 Code here and on ${node}: done`)).toBeLessThan(output.lastIndexOf(`Left for you on ${node}:`));
    const left = endList(output).split("\n");
    expect([left[0], left.at(-1)]).toEqual([`Left for you on ${node}:`, `Do each one, then run hedge apply on ${node}.`]);
    expect(left).toHaveLength(4);
    expect([listed(output, "Install the signed Git allowlist as root"), listed(output, "Install earlyoom as root")]).toEqual([1, 1]);
    const printed = left.slice(1, -1).map((line) => line.slice(line.indexOf(" Run: ") + " Run: ".length));
    expect(printed.map((command) => throughSsh(home, node, command))).toEqual([0, 0]);
    expect([nodeHas(home, node, "allowlist"), nodeHas(home, node, "earlyoom")]).toEqual([true, true]);
  });

  test("goes on to the link step when only the person's sign-ins are left", async () => {
    const { home, io, add } = await signedUp(["--add", "integrations", "--plan", "both"]);
    const box = fakeMachine(home, {}, { node: { signedOut: true } });
    expect(await add(box)).toBe(0);
    expect(box.peerLinks.here).toEqual(linkedHere);
    expect(io.output()).toContain(`  ✓ Link T3 Code here and on ${node}: done`);
  });

  test("still lists the steps left for the person when a later step fails", async () => {
    const { home, io, add } = await signedUp(guarded);
    expect(await add(fakeMachine(home, {}, { node: {}, serverWithoutLinkState: ["box"] }))).toBe(1);
    const output = io.output();
    expect(output).toContain(`hedge: ${node} has no T3 Connect address yet.`);
    const left = endList(output).split("\n");
    expect(left.slice(0, 4).filter((line) => line.startsWith("  · Install "))).toHaveLength(2);
    expect(left[3]).toBe(`Do each one, then run hedge apply on ${node}.`);
  });

  test("stops at the profile step, links nothing, when the apply fails for another reason, and a rerun after the fix applies the profile and links the node", async () => {
    const { home, io, add } = await signedUp(guarded);
    const failed = fakeMachine(home, {}, notTheProfile);
    expect(await add(failed)).toBe(1);
    expect(failed.peerLinks).toEqual({ box: [], here: [] });
    expect(io.output()).not.toContain(`Left for you on ${node}:`);
    expect(io.output().slice(io.output().lastIndexOf("hedge: "))).toStartWith(`hedge: The devbox could not apply your profile.`);
    const fixed = fakeMachine(home, {}, { node: { allowlist: true } });
    expect(await add(fixed)).toBe(0);
    expect(profileApplied(home)).toBe(true);
    expect(fixed.peerLinks.here).toEqual(linkedHere);
  });

  test("stops at the profile step, and names what else the node finds, when a check that is no step for the person fails beside one that is", async () => {
    const { home, io, add } = await signedUp(guarded);
    const box = fakeMachine(home, {}, { node: { allowlist: true, oldSystemd: true } });
    expect(await add(box)).toBe(1);
    expect(box.peerLinks).toEqual({ box: [], here: [] });
    const failure = io.output().slice(io.output().lastIndexOf("hedge: ")).split("\n");
    expect(failure[0]).toBe(`hedge: Your profile applied on ${node}, but hedge doctor there finds more than steps for you. Fix what it says, then run hedge devbox add ${node} again.`);
    expect(failure.filter((line) => line.includes("systemd older than 253"))).toHaveLength(1);
    expect(failure.filter((line) => line.startsWith("  · Install earlyoom as root"))).toHaveLength(1);
    expect(io.output()).not.toContain(`Left for you on ${node}:`);
  });

  test("names what hedge doctor on the node finds when the apply fails, though the apply printed none of it", async () => {
    const { home, io, add } = await signedUp(guarded);
    expect(await add(fakeMachine(home, {}, { node: { stepsFail: true } }))).toBe(1);
    const failure = io.output().slice(io.output().lastIndexOf("hedge: ")).split("\n");
    expect(failure[0]).toStartWith("hedge: The devbox could not apply your profile.");
    expect(failure.filter((line) => line.includes("systemd older than 253"))).toHaveLength(1);
  });

  test("finishes the profile step, and points to hedge doctor on the node, when the node runs an older Hedge without --to-do", async () => {
    const { home, io, add } = await signedUp(guarded);
    const box = fakeMachine(home, {}, { node: { olderEngine: true } });
    expect(await add(box)).toBe(0);
    expect(io.output()).toContain(`  · ${node} runs an older Hedge, which cannot list the steps left for you. Run hedge doctor on ${node} to see them.`);
    expect(io.output()).not.toContain(`Left for you on ${node}:`);
    expect(profileApplied(home)).toBe(true);
    expect(box.peerLinks.here).toEqual(linkedHere);
  });

  test("takes the steps left from the node's own profile, not from this machine's", async () => {
    const { home, io, add } = await signedUp(guarded);
    const clone = join(boxHome(home, node), ".local/share/hedge/profile");
    git(home, "clone", "-q", githubRepo(home, "nora/nora-hedge"), clone);
    const answers = JSON.parse(readFileSync(join(clone, "hedge.json"), "utf8"));
    writeFileSync(join(clone, "hedge.json"), JSON.stringify({ ...answers, packs: answers.packs.filter((pack: string) => pack !== "guards") }, null, 2) + "\n");
    git(clone, "commit", "-q", "-am", "The node's profile, before guards");
    expect(await add(fakeMachine(home, {}, { node: {} }))).toBe(0);
    expect([nodeHas(home, node, "allowlist"), nodeHas(home, node, "earlyoom")]).toEqual([false, false]);
    expect(io.output()).not.toContain(`Left for you on ${node}:`);
  });

  test("keeps the installed engine and its packages when the engine sits at this machine's commit, and applies the profile with it", async () => {
    const { home, add } = await signedUp();
    expect(await add(fakeMachine(home, {}, notTheProfile))).toBe(1);
    writeFileSync(enginePath(home, "node_modules/kept"), "");
    expect(await add(fakeMachine(home, {}, { node: {} }))).toBe(0);
    expect(existsSync(enginePath(home, "node_modules/kept"))).toBe(true);
    expect(nodeEngine(home, node)).toMatchObject({ commit: thisCommit, runs: true });
    expect(profileApplied(home)).toBe(true);
  });

  test("installs again with get.sh when the engine has moved to another commit since the install step", async () => {
    const { home, add } = await signedUp();
    expect(await add(fakeMachine(home, {}, notTheProfile))).toBe(1);
    expect(await add(fakeMachine(home, {}, { node: { engineAt: "1".repeat(40) } }))).toBe(0);
    expect(nodeEngine(home, node)).toMatchObject({ commit: thisCommit, runs: true });
    expect(profileApplied(home)).toBe(true);
  });

  test("finishes on the next run an install that stopped before the engine's packages", async () => {
    const { home, add } = await signedUp();
    expect(await add(fakeMachine(home, {}, { node: { installFails: true } }))).toBe(1);
    expect(nodeEngine(home, node)).toMatchObject({ commit: thisCommit, runs: false });
    expect(await add(fakeMachine(home, {}, { node: {} }))).toBe(0);
    expect(nodeEngine(home, node).runs).toBe(true);
    expect(profileApplied(home)).toBe(true);
  });

  test("installs again with get.sh when the engine sits at this machine's commit but its launcher does not run", async () => {
    const { home, add } = await signedUp();
    expect(await add(fakeMachine(home, {}, notTheProfile))).toBe(1);
    writeFileSync(join(boxHome(home, node), ".node/packages-missing"), "");
    expect(nodeEngine(home, node)).toMatchObject({ commit: thisCommit, runs: false });
    expect(await add(fakeMachine(home, {}, { node: {} }))).toBe(0);
    expect(nodeEngine(home, node)).toMatchObject({ commit: thisCommit, runs: true });
    expect(profileApplied(home)).toBe(true);
  });
});

import { afterEach, describe, expect, test } from "bun:test";
import { readFileSync, rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { isolateGit, spawnGit, tempDirs } from "../testing/git.ts";
import { profilePath } from "./profile.ts";
import { changeOnFirstCommit as changeOnFirstCommitIn, fakeMachine, hedgeSetup, githubRepo, pushedAnswers } from "./testing.ts";

isolateGit();
const temp = tempDirs();
afterEach(() => temp.cleanup());

async function nameHub(profile: string) {
  const answers = JSON.parse(readFileSync(join(profile, "hedge.json"), "utf8"));
  if (answers.hub) return;
  writeFileSync(join(profile, "hedge.json"), JSON.stringify({ ...answers, hub: "coder.hedge-hub" }, null, 2) + "\n");
  await spawnGit(profile, "commit", "-q", "-am", "Name the hub");
  await spawnGit(profile, "push", "-q");
}

describe("hedge setup with a devbox", () => {
  test("asks the settings only a devbox needs once a devbox is added, saves them to the profile before the box applies it, and a run without a person lists them", async () => {
    const question = "? Which T3 project do the loops and the PR digest run in?";
    const args = ["--preset", "everyday", "--plan", "claude", "--workflows", "pr-digest=on"];
    const alone = temp.make("home-");
    expect((await hedgeSetup(alone, [...args, "--devbox", "skip"], ["", ""], fakeMachine(alone))).output).not.toContain(question);

    const home = temp.make("home-");
    const result = await hedgeSetup(home, [...args, "--devbox", "node-1"], ["", "", "~/code/app"], fakeMachine(home));
    expect(result.code).toBe(0);
    const output = result.output;
    expect(output.indexOf(question)).toBeGreaterThan(output.indexOf("  ✓ node-1"));
    expect(output.indexOf(question)).toBeLessThan(output.indexOf("▶ Install Hedge on node-1"));
    expect((await pushedAnswers(home)).settings["orchestration.loopProject"]).toBe("~/code/app");

    const later = temp.make("home-");
    const waiting = await hedgeSetup(later, ["--non-interactive", ...args, "--devbox", "node-9"], [], fakeMachine(later));
    expect(waiting.code).toBe(2);
    expect(waiting.output).toContain("  --set orchestration.loopProject=<value>   Which T3 project do the loops and the PR digest run in?");
  });

  test("goes on to link T3 Code when hedge doctor on the devbox finds only to-dos that wait for the person's sign-ins", async () => {
    const home = temp.make("home-");
    const result = await hedgeSetup(home, ["--preset", "starter", "--plan", "both", "--add", "integrations", "--devbox", "node-1"], ["", ""], fakeMachine(home, {}, { node: { signedOut: true } }));
    expect(result.output).toContain("  ✓ Link T3 Code here and on node-1: done");
  });

  test("a devbox setting whose push failed is pushed on the next run before the box is installed", async () => {
    const args = ["--preset", "everyday", "--plan", "claude", "--workflows", "pr-digest=on", "--devbox", "node-1"];
    const home = temp.make("home-");
    expect((await hedgeSetup(home, args, ["", ""], fakeMachine(home))).code).toBe(130);
    const rejecting = join(githubRepo(home, "nora/nora-hedge"), "hooks/pre-receive");
    writeFileSync(rejecting, "#!/bin/sh\nexit 1\n", { mode: 0o755 });
    expect((await hedgeSetup(home, args, ["~/code/app"], fakeMachine(home))).output).toContain("could not push answers");

    const blocked = await hedgeSetup(home, ["--non-interactive", ...args], [], fakeMachine(home));
    expect(blocked.output).toContain("could not push answers: ! [remote rejected] HEAD -> main (pre-receive hook declined). Fix that, then try again.");
    expect(blocked.output).not.toContain("▶ Install Hedge on node-1");

    rmSync(rejecting);
    expect((await hedgeSetup(home, ["--non-interactive", ...args], [], fakeMachine(home))).code).toBe(0);
    expect((await pushedAnswers(home)).settings["orchestration.loopProject"]).toBe("~/code/app");
  });

  const devboxArgs = ["--preset", "everyday", "--plan", "claude", "--workflows", "pr-digest=on", "--devbox", "node-1"];

  const changeOnFirstCommit = (home: string, change: string) => changeOnFirstCommitIn(home, join(temp.make("elsewhere-"), "profile"), change);

  test("a devbox setting whose push comes after a non-profile push retries once with fetch and rebase and saves both", async () => {
    const home = temp.make("home-");
    expect((await hedgeSetup(home, devboxArgs, ["", ""], fakeMachine(home))).code).toBe(130);
    await changeOnFirstCommit(home, 'await Bun.write("about-me.md", "# Changed on another machine\\n");');

    const retried = await hedgeSetup(home, devboxArgs, ["~/code/app"], fakeMachine(home));

    expect(retried.code).toBe(0);
    expect((await pushedAnswers(home)).settings).toEqual({ "context.repo": "nora/nora-hedge", "orchestration.loopProject": "~/code/app" });
    expect(await spawnGit(home, "--git-dir", githubRepo(home, "nora/nora-hedge"), "show", "main:about-me.md")).toBe("# Changed on another machine");
  });

  test("stops when another machine changes the same devbox setting before the push, and after setup's commit is dropped the same command run again saves this run's answer", async () => {
    const home = temp.make("home-");
    expect((await hedgeSetup(home, devboxArgs, ["", ""], fakeMachine(home))).code).toBe(130);
    await changeOnFirstCommit(home, 'profile.settings = { ...profile.settings, "orchestration.loopProject": value };');

    const stopped = await hedgeSetup(home, devboxArgs, ["~/code/app"], fakeMachine(home));

    expect(stopped.code).toBe(1);
    expect(stopped.output).toContain(`hedge: another machine pushed to your profile before setup could.`);
    expect((await pushedAnswers(home)).settings).toEqual({ "context.repo": "nora/nora-hedge", "orchestration.loopProject": "after" });
    await spawnGit(profilePath(home), "reset", "-q", "--keep", "@{upstream}");
    expect((await hedgeSetup(home, devboxArgs, ["~/code/app"], fakeMachine(home))).code).toBe(0);
    expect((await pushedAnswers(home)).settings).toEqual({ "context.repo": "nora/nora-hedge", "orchestration.loopProject": "~/code/app" });
  });

  test("a checkout with an unrelated staged file that diverged from origin gets advice that lets the same command run again save the devbox setting", async () => {
    const home = temp.make("home-");
    const dir = profilePath(home);
    expect((await hedgeSetup(home, devboxArgs, ["", ""], fakeMachine(home))).code).toBe(130);
    const elsewhere = join(temp.make("elsewhere-"), "profile");
    await spawnGit(home, "clone", "-q", githubRepo(home, "nora/nora-hedge"), elsewhere);
    writeFileSync(join(elsewhere, "about-me.md"), "# Changed on another machine\n");
    await spawnGit(elsewhere, "commit", "-q", "-am", "Change about me on another machine");
    await spawnGit(elsewhere, "push", "-q");
    writeFileSync(join(dir, "README.md"), "# Changed here\n");
    await spawnGit(dir, "commit", "-q", "-am", "Change the guide here");
    writeFileSync(join(dir, "notes.md"), "draft\n");
    await spawnGit(dir, "add", "notes.md");

    const stopped = await hedgeSetup(home, devboxArgs, ["~/code/app"], fakeMachine(home));

    expect(stopped.code).toBe(1);
    expect(stopped.output).toContain(`hedge: ${dir} and origin both have changes the other lacks. Commit or discard the changes in ${dir} that are not committed. Bring it up to date with git -C ${dir} pull --rebase, then run the same hedge setup command again.`);
    await spawnGit(dir, "rm", "-q", "-f", "notes.md");
    await spawnGit(dir, "pull", "-q", "--rebase");
    const rerun = await hedgeSetup(home, devboxArgs, ["~/code/app"], fakeMachine(home));
    expect(rerun.code).toBe(0);
    expect((await pushedAnswers(home)).settings).toEqual({ "context.repo": "nora/nora-hedge", "orchestration.loopProject": "~/code/app" });
    const onOrigin = (path: string) => spawnGit(home, "--git-dir", githubRepo(home, "nora/nora-hedge"), "show", `main:${path}`);
    expect([await onOrigin("about-me.md"), await onOrigin("README.md")]).toEqual(["# Changed on another machine", "# Changed here"]);
  });

  test("hedge setup --devbox lists the node in the profile, and the hub takes it before the node asks it for a credential and links it in T3 Code once the node runs T3", async () => {
    const home = temp.make("home-");
    const box = fakeMachine(home);
    const result = await hedgeSetup(home, ["--preset", "starter", "--plan", "claude", "--devbox", "coder.hedge-node-1"], ["", "", ""], box, undefined, 0, "linux", nameHub);
    expect(result.code).toBe(0);
    expect((await pushedAnswers(home)).devboxes).toEqual(["coder.hedge-node-1"]);
    expect(box.hubUpdates).toEqual(["coder.hedge-hub"]);
    expect(box.credentials).toEqual([{ node: "coder.hedge-node-1", issued: true }]);
    expect(result.output).toContain("✓ The hub, coder.hedge-hub, took coder.hedge-node-1: its disk watch, tunnels and credentials include it now.");
    expect(box.hubLinked).toEqual(["coder.hedge-node-1"]);
    expect(result.output).toContain("✓ The hub, coder.hedge-hub, linked coder.hedge-node-1 in T3 Code.");
  });

  test("hedge setup run again has the hub take the node, then applies the node's profile and links it from the hub, when the hub could not take it on an earlier run that stopped or finished", async () => {
    for (const [polls, firstCode] of [[{ "box:github": 1 }, 2], [{}, 0]] as const) {
      const home = temp.make("home-");
      const args = ["--non-interactive", "--preset", "starter", "--plan", "claude", "--devbox", "coder.hedge-node-1"];
      for (const hubUpdateFails of ["hedge update: the engine has local changes.", undefined]) {
        const failing = fakeMachine(home, polls, hubUpdateFails ? { hubUpdateFails } : { hubDown: true });
        expect((await hedgeSetup(home, args, [], failing, undefined, 0, "linux", nameHub)).code).toBe(firstCode);
      }
      const box = fakeMachine(home);
      expect((await hedgeSetup(home, args, [], box, undefined, 0, "linux", nameHub)).code).toBe(0);
      expect(box.hubUpdates).toEqual(["coder.hedge-hub"]);
      expect(box.credentials).toEqual([{ node: "coder.hedge-node-1", issued: true }]);
      expect(box.hubLinked).toEqual(["coder.hedge-node-1"]);
    }
  });
});

import { afterEach, describe, expect, test } from "bun:test";
import { mkdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { main } from "../cli.ts";
import { loadPacks } from "../pack/manifest.ts";
import type { FetchedSource, PackSetting, SourceRef } from "../pack/types.ts";
import { isolateGit, spawnGit, tempDirs } from "../testing/git.ts";
import { parseSetupFlags } from "./flags.ts";
import { profilePath } from "./profile.ts";
import { packList, settingSteps, type Catalog, type Draft } from "./questions.ts";
import { engineRoot, fakeMachine, githubRepo, machineFile, pushedAnswers, scripted } from "./testing.ts";

isolateGit();
const temp = tempDirs();
afterEach(() => temp.cleanup());

const region: PackSetting = {
  key: "team.region",
  question: "Where should your devbox run?",
  type: "choice",
  choices: [
    { value: "us", label: "US" },
    { value: "eu", label: "EU" },
  ],
  default: "us",
  defaultByTimeZone: { "Europe/": "eu", "America/": "us" },
  ask: "setup",
};

const teamRegion: PackSetting = { ...region, key: "posthog.region" };

function teamSource(settings: PackSetting[], name = "posthog"): (ref: SourceRef) => Promise<FetchedSource> {
  const dir = temp.make("team-");
  mkdirSync(join(dir, "packs", name), { recursive: true });
  writeFileSync(join(dir, "packs", name, "pack.json"), JSON.stringify({ schema: 1, name, summary: "Team rules.", settings }));
  return async (ref) => ({ ref, dir, packs: await loadPacks(dir) });
}

async function unattendedSetup(home: string, timeZone: string, { settings = [teamRegion], plan = "claude", set = [] as string[], picks = ["--preset", "starter", "--devbox", "skip"], pack = "posthog" } = {}) {
  const io = scripted([]);
  const box = fakeMachine(home, {}, { org: true });
  return main(["setup", "--non-interactive", ...picks, "--plan", plan, ...set.flatMap((value) => ["--set", value])], { home, engineRoot, platform: "linux", print: io.terminal.print, terminal: io.terminal, apply: async () => 0, setup: { machine: box.machine, clock: box.clock, doctor: async () => 0, env: {}, timeZone, fetchSource: teamSource(settings, pack) } });
}

async function pushFromAnotherMachine(home: string, settings: Record<string, string>) {
  const other = temp.make("other-");
  await spawnGit(other, "clone", "-q", githubRepo(home, "nora/nora-hedge"), ".");
  const file = JSON.parse(readFileSync(join(other, "hedge.json"), "utf8"));
  writeFileSync(join(other, "hedge.json"), JSON.stringify({ ...file, settings: { ...file.settings, ...settings } }, null, 2) + "\n");
  await spawnGit(other, "commit", "-q", "-am", "Elsewhere");
  await spawnGit(other, "push", "-q");
}

async function ask(timeZone: string | undefined, args: string[] = []) {
  const lines: string[] = [];
  const draft: Draft = {};
  const terminal = { print: (line: string) => void lines.push(line), ask: async () => "" };
  const context = { terminal, flags: parseSetupFlags(args), catalog: {} as Catalog, draft, timeZone, answer: async (fields: Draft) => void Object.assign(draft, fields) };
  await settingSteps(context, [region])[0]!.run();
  return { settings: draft.settings, output: lines.join("\n") };
}

describe("a setting's time-zone default", () => {
  test("picks eu in Europe/Berlin", async () => {
    const result = await ask("Europe/Berlin");
    expect(result.output).toContain("  2) EU (default)");
    expect(result.settings).toEqual({ "team.region": "eu" });
  });

  test("picks us in America/New_York", async () => {
    expect((await ask("America/New_York")).settings).toEqual({ "team.region": "us" });
  });

  test("falls back to the static default in a zone the map does not name", async () => {
    const result = await ask("Asia/Tokyo");
    expect(result.output).toContain("  1) US (default)");
    expect(result.settings).toEqual({ "team.region": "us" });
  });

  test("--non-interactive saves the time-zone default to the pushed profile", async () => {
    const home = temp.make("home-");
    expect(await unattendedSetup(home, "Europe/Lisbon")).toBe(0);
    expect((await pushedAnswers(home)).settings).toEqual({ "posthog.region": "eu" });
  });

  test("--non-interactive on another machine keeps the region the profile already has", async () => {
    const home = temp.make("home-");
    expect(await unattendedSetup(home, "America/New_York")).toBe(0);
    rmSync(join(home, ".config/hedge"), { recursive: true });
    rmSync(profilePath(home), { recursive: true });
    expect(await unattendedSetup(home, "Europe/Lisbon")).toBe(0);
    expect((await pushedAnswers(home)).settings).toEqual({ "posthog.region": "us" });
  });

  test("--non-interactive on a machine whose profile clone is behind keeps the region another machine pushed", async () => {
    const home = temp.make("home-");
    expect(await unattendedSetup(home, "Europe/Lisbon", { settings: [] })).toBe(0);
    await pushFromAnotherMachine(home, { "posthog.region": "us" });
    expect(await unattendedSetup(home, "Europe/Lisbon", { plan: "both" })).toBe(0);
    expect(await pushedAnswers(home)).toMatchObject({ plan: "both", settings: { "posthog.region": "us" } });
  });

  test("treats a machine without a time zone as one the map does not name", async () => {
    const result = await ask(undefined);
    expect(result.output).toContain("  1) US (default)");
    expect(result.settings).toEqual({ "team.region": "us" });
  });
});

describe("a time-zone default that setup saved before it stopped", () => {
  const teamName: PackSetting = { key: "posthog.team", question: "Which team are you on?", type: "string", ask: "setup" };
  const forget = (home: string) => {
    rmSync(join(home, ".config/hedge"), { recursive: true });
    rmSync(profilePath(home), { recursive: true });
  };

  test("gives way to the answer another machine pushed while setup was stopped", async () => {
    const home = temp.make("home-");
    expect(await unattendedSetup(home, "Asia/Tokyo", { settings: [] })).toBe(0);
    forget(home);
    expect(await unattendedSetup(home, "Europe/Lisbon", { settings: [teamRegion, teamName] })).toBe(2);
    await pushFromAnotherMachine(home, { "posthog.region": "us" });
    expect(await unattendedSetup(home, "Europe/Lisbon", { settings: [teamRegion, teamName], set: ["posthog.team=web"] })).toBe(0);
    expect((await pushedAnswers(home)).settings).toEqual({ "posthog.region": "us", "posthog.team": "web" });
  });

  test("still lands when no machine answered it in the meantime", async () => {
    const home = temp.make("home-");
    expect(await unattendedSetup(home, "Europe/Lisbon", { settings: [teamRegion, teamName] })).toBe(2);
    expect(await unattendedSetup(home, "Europe/Lisbon", { settings: [teamRegion, teamName], set: ["posthog.team=web"] })).toBe(0);
    const pushed = await pushedAnswers(home);
    expect(pushed.settings).toEqual({ "posthog.region": "eu", "posthog.team": "web" });
    expect(Object.keys(pushed).sort()).toEqual(["engine", "migrations", "packs", "plan", "schema", "settings", "sources", "workflows"]);
  });

  test("gives way there too when a devbox setting is pushed after the profile is saved", async () => {
    const home = temp.make("home-");
    const team = { settings: [{ ...region, key: "acme.region" }, { ...teamName, key: "acme.team" }], pack: "acme", picks: ["--preset", "everyday", "--workflows", "pr-digest=on", "--devbox", "node-1"] };
    expect(await unattendedSetup(home, "Asia/Tokyo", { ...team, settings: [], set: ["orchestration.loopProject=~/code/app"] })).toBe(0);
    forget(home);
    expect(await unattendedSetup(home, "Europe/Lisbon", team)).toBe(2);
    await pushFromAnotherMachine(home, { "acme.region": "us" });
    expect(await unattendedSetup(home, "Europe/Lisbon", { ...team, set: ["acme.team=web", "orchestration.loopProject=~/code/web"] })).toBe(0);
    expect((await pushedAnswers(home)).settings).toEqual({ "acme.region": "us", "acme.team": "web", "context.repo": "nora/nora-hedge", "orchestration.loopProject": "~/code/web" });
  });

  test("stays out of the draft an older engine would resume as answers", async () => {
    const home = temp.make("home-");
    expect(await unattendedSetup(home, "Europe/Lisbon", { settings: [teamRegion, teamName] })).toBe(2);
    expect(machineFile(home).setup.draft.settings ?? {}).toEqual({});
  });

  test("an explicit answer on the resumed run wins over another machine's", async () => {
    const home = temp.make("home-");
    expect(await unattendedSetup(home, "Asia/Tokyo", { settings: [] })).toBe(0);
    forget(home);
    expect(await unattendedSetup(home, "Europe/Lisbon", { settings: [teamRegion, teamName] })).toBe(2);
    await pushFromAnotherMachine(home, { "posthog.region": "us" });
    expect(await unattendedSetup(home, "Europe/Lisbon", { settings: [teamRegion, teamName], set: ["posthog.team=web", "posthog.region=eu"] })).toBe(0);
    expect((await pushedAnswers(home)).settings).toEqual({ "posthog.region": "eu", "posthog.team": "web" });
  });
});

describe("a pack's name in setup", () => {
