test("an operation failure rolls back earlier changes and keeps ownership state", async () => {
  const { home } = await fixture();
  await install(home, [{ target: "settings", content: "original" }]);
  const state = join(home, ".local/state/hedge/state.json");
  const before = await readFile(state, "utf8");
  // A missing parent passes inspection. Creating the long filename then fails.
  await expect(install(home, [
    { target: "settings", content: "updated" },
    { target: `parent/${"x".repeat(256)}`, content: "cannot write" },
  ])).rejects.toThrow();
  expect(await readFile(join(home, "settings"), "utf8")).toBe("original");
  expect(await readFile(state, "utf8")).toBe(before);
  expect((await lstat(join(home, "parent"))).isDirectory()).toBe(true);
  expect((await install(home, [{ target: "settings", content: "original" }])).actions[0]?.operation).toBe("keep");
});


test("managed targets cannot replace Hedge state through ancestors or aliases", async () => {
  const { home } = await fixture();
  await install(home, [{ target: "settings", content: "original" }]);
  const state = join(home, ".local/state/hedge/state.json");
  const before = await readFile(state, "utf8");
  for (const target of [".local", ".local/state", ".local/state/hedge", ".local/state/./hedge/state.json"]) {
    await expect(install(home, [
      { target: "settings", content: "updated" },
      { target, content: "would replace state" },
    ], "core", { adopt: [target] })).rejects.toThrow();
    expect(await readFile(state, "utf8")).toBe(before);
    expect(await readFile(join(home, "settings"), "utf8")).toBe("original");
  }
});

test("a hedge record of a file in a path from before the rename is dropped, and the file stays", async () => {
  const { home } = await fixture();
  await mkdir(join(home, ".config/fleet/hooks"), { recursive: true });
  await writeFile(join(home, ".config/fleet/hooks/run.sh"), "old hook\n");
  await install(home, [{ target: "kept", content: "kept\n" }], "hedge");
  const state = join(home, ".local/state/hedge/state.json");
  const owned = JSON.parse(await readFile(state, "utf8"));
  owned.groups.hedge[".config/fleet/hooks/run.sh"] = { kind: "file", hash: new Bun.CryptoHasher("sha256").update("old hook\n").digest("hex") };
  await writeFile(state, JSON.stringify(owned));

  await install(home, [{ target: "kept", content: "kept\n" }], "hedge");

  expect(await readFile(join(home, ".config/fleet/hooks/run.sh"), "utf8")).toBe("old hook\n");
  expect(Object.keys(JSON.parse(await readFile(state, "utf8")).groups.hedge)).toEqual(["kept"]);
});

